package com.yuegang.zhihui.search.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.search.application.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/internal/v1/search")public final class SearchController{private final HybridSearchService service;public SearchController(HybridSearchService s){service=s;}@PostMapping("/hybrid")ApiResponse<List<SearchHit>>search(@Valid @RequestBody SearchRequest body,HttpServletRequest r){return ApiResponse.success(service.search(body),TraceIdResolver.resolve(r));}@PostMapping("/index")ApiResponse<Map<String,Boolean>>index(@Valid @RequestBody IndexChunkCommand body,HttpServletRequest r){service.index(body);return ApiResponse.success(Map.of("completed",true),TraceIdResolver.resolve(r));}}
